def find_increasing_sequence(n, b):
    # Helper function to check if the sequence a_i is strictly increasing
    def is_strictly_increasing(a):
        for i in range(1, len(a)):
            if a[i] <= a[i - 1]:
                return False
        return True

    # Generate all permutations of b and check if any of them results in a strictly increasing sequence a_i
    from itertools import permutations

    for perm in permutations(b):
        a = [perm[0]]
        for i in range(1, n):
            a.append(a[i - 1] ^ perm[i])
        if is_strictly_increasing(a):
            return 'Yes', perm

    return 'No', []

# Read input
